$\begin{aligned}
& \mathrm{R}=\frac{\rho \cdot l}{\mathrm{~A}} \\
& l_{\mathrm{B}}=2 l_{\mathrm{A}} \quad \text { also } \quad r_{\mathrm{A}}=2 r_{\mathrm{B}} \\
& \therefore \quad \mathrm{~A}_{\mathrm{A}}=4 \mathrm{~A}_{\mathrm{B}}
\end{aligned}\begin{aligned}
\therefore \quad \frac{\mathrm{R}_{\mathrm{A}}}{\mathrm{R}_{\mathrm{B}}} & =\frac{\mathrm{l}_{\mathrm{A}} \cdot \mathrm{~A}_{\mathrm{B}}}{1_{\mathrm{B}} \cdot \mathrm{~A}_{\mathrm{A}}} \\
& =\frac{1}{2} \cdot \frac{1}{4}=1: 8
\end{aligned}$

